"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[8302],{7738(e){e.exports=JSON.parse('{"title":"State of HTML 2023","date":"2024-05-22","coverUrl":null,"html":"<h2 data-notion-block-id=\\"94517f9e-4d74-4d70-8dd2-2c70ed1a5099\\" id=\\"94517f9e-4d74-4d70-8dd2-2c70ed1a5099\\">State of HTML 2023</h2><a href=\\"https://2023.stateofhtml.com/en-US/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://2023.stateofhtml.com/en-US/</a><p data-notion-block-id=\\"1af18253-c617-4077-a3d0-b2b8df966a6e\\"><b>\uc2ec\uc724\uc12d</b>: HTML\uc5d0\ub294 \uc5b4\ub5a4 \uae30\ub2a5\uc774 \uc788\ub294\uc9c0\uc640 HTML\uc5d0 \ub300\ud574 \ub2e4\ub978 \uc0ac\ub78c\uc740 \uc5b4\ub5bb\uac8c \uc0dd\uac01\ud558\ub294\uc9c0 \uc5ff\ubcfc \uc218 \uc788\ub294 \uc124\ubb38\uc870\uc0ac \uacb0\uacfc\uc785\ub2c8\ub2e4. HTML\uc744 \ud1b5\ud574 \uad6c\uc870\ub97c \uc124\uacc4\ud574\uc57c \ud558\uace0, HTML\uc5d0 \uad00\ub828\ub41c JS API\uc5d0 \ub300\ud55c \uc124\ubb38\ub3c4 \uc788\uc73c\ubbc0\ub85c \ub458\ub7ec\ubcf4\uba74 \uc88b\uc740 \uc124\ubb38\uc870\uc0ac\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"b8cff951-c514-4bd3-b95c-d2b8d2bd73f9\\" id=\\"b8cff951-c514-4bd3-b95c-d2b8d2bd73f9\\">Rate Limit \uc54c\uace0\ub9ac\uc998 \uc2dc\uac01\ud654</h2><a href=\\"https://smudge.ai/blog/ratelimit-algorithms\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://smudge.ai/blog/ratelimit-algorithms</a><p data-notion-block-id=\\"893d8a41-a7c4-4a12-b95d-1214912a394b\\"><b>\uc2ec\uc724\uc12d</b>: Rate limit\ub294 \uc11c\ube44\uc2a4\uc758 \ud2b8\ub798\ud53d\uc744 \uad00\ub9ac\ud558\ub294 \uc911\uc694\ud55c \ub85c\uc9c1\uc785\ub2c8\ub2e4. \uc704\ud5d8\ud55c \uacf5\uaca9\uc778 Brute force\uc5d0 \ub300\ud574 \ub9c9\uc744 \uc218\ub3c4 \uc788\uc8e0. \uc54c\uace0\ub9ac\uc998\uc744 \uc18c\uac1c\ud558\ub294 \uac83\uacfc \ub3d9\uc2dc\uc5d0 \uc2dc\uac01\ud654\ub97c \ud574\uc8fc\ub294 \uc88b\uc740 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"03015441-9491-46f3-b397-b579347a0081\\" id=\\"03015441-9491-46f3-b397-b579347a0081\\">ESLint 9.0 \uc548\uc815\ud654</h2><a href=\\"https://eslint.org/blog/2024/05/eslint-compatibility-utilities/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://eslint.org/blog/2024/05/eslint-compatibility-utilities/</a><p data-notion-block-id=\\"8985aa9c-9d91-4aa1-9c99-3424273e15a9\\">ESLint\ub294 \ub9ce\uc740 \ucee4\ubba4\ub2c8\ud2f0\uc5d0 \uc758\ud574 \uad74\ub7ec\uac11\ub2c8\ub2e4. \uadf8\ub798\uc11c \ucee4\ubba4\ub2c8\ud2f0 \ud50c\ub7ec\uadf8\uc778\ub4e4\uc758 \ubc84\uc804 \uc9c0\uc6d0\uc744 \uacc4\uc18d \ud574\uc8fc\ub294 \uac83\uc774 \uc911\uc694 \ud3ec\uc778\ud2b8\uac00 \ub429\ub2c8\ub2e4. ESLint\uac00 9.0\uc744 \uc9c0\uc6d0\ud558\uba74\uc11c \ub0b4\ubd80 \ub3d9\uc791 \ubc29\uc2dd\uacfc Flat Config\ub97c \ucd9c\uc2dc\ud574\uc11c \uc774\uc804 \ubc84\uc804\uacfc \ud638\ud658\uc774 \uc548\ub418\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc558\ub294\ub370 ESLint \ud300\uc5d0\uc11c \uc774\ub97c \ub77c\uc774\ube0c\ub7ec\ub9ac\ub85c \ud574\uc18c\ud588\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c <a href=\\"https://github.com/eslint/eslint/issues/18391\\">ESLint 9\ubc84\uc804 \uc9c0\uc6d0</a>\uacfc <a href=\\"https://github.com/eslint/eslint/issues/18093\\">Flat Config \uc9c0\uc6d0</a>\uc744 \ubcf4\uace0 <a href=\\"https://www.npmjs.com/package/@eslint/eslintrc\\"><code>@eslint/eslintrc</code></a>\uc640 <a href=\\"https://www.npmjs.com/package/@eslint/compat\\"><code>@eslint/compat</code></a>\uc744 \uc798 \uc368\uc11c 9\ubc84\uc804\uc73c\ub85c \ubc84\uc804\uc5c5 \ud574\uc57c\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"2e516072-53b2-4b04-b9ab-c19d1642e04b\\" id=\\"2e516072-53b2-4b04-b9ab-c19d1642e04b\\">React \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc744 \ub9cc\ub4e4 \ub54c \uc0dd\uac01\ud560 \uac83</h2><a href=\\"https://github.com/alan2207/bulletproof-react/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/alan2207/bulletproof-react/</a><p data-notion-block-id=\\"3f5a1af8-c541-4bf2-9730-14ef2c2d20ef\\"><b>\uc2ec\uc724\uc12d</b>: React \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc744 \ub9cc\ub4e4 \ub54c \ub77c\uc774\ube0c\ub7ec\ub9ac \uc120\ud0dd\ud558\uac70\ub098 \ucf54\ub4dc \ubc16\uc5d0\uc11c \uace0\ub824\ud574\uc57c \ud560 \uac83\uc740 \uacf5\uc2dd\ubb38\uc11c\uc5d0\uc11c \uc54c\ub824\uc8fc\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc740 \uc790\uc2e0\uc758 \uc8fc\uad00\uacfc \ud568\uaed8 \uace0\ub824\ud560 \uc810\uc744 \ucd94\ub824\uc11c \uc54c\ub824\uc8fc\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc774\uc678\uc5d0\ub3c4 \ub2e4\ub978 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc640 \ub2e4\ub978 \uace0\ub824\ud560 \uac83\uc740 \ub9ce\uc9c0\ub9cc \uc8fc\uc694 \ubd80\ubd84\uc740 \ubaa8\ub450 \uc124\uba85\ud55c\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2d01841e-9fc5-4807-99d5-d8d2a73be23e\\" id=\\"2d01841e-9fc5-4807-99d5-d8d2a73be23e\\">React \ub0b4\ubd80 \ub525 \ub2e4\uc774\ube0c</h2><a href=\\"https://jser.dev/series/react-source-code-walkthrough\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jser.dev/series/react-source-code-walkthrough</a><p data-notion-block-id=\\"5908d1f8-f5e2-41c0-ad95-25506caaba15\\"><b>\uc2ec\uc724\uc12d</b>: <a href=\\"https://ones-to-watch.ethansup.net/news/post/ce8b03b6-8565-440b-9d22-36c9ed0f58db#3107fecb-1574-47c1-94f0-f1a53442a6a4\\">React\uc758 \ub3d9\uc2dc\ubaa8\ub4dc \uc791\ub3d9 \uc6d0\ub9ac</a>\uc5d0\uc11c \uac00\uc838\uc654\ub4ef\uc774 React\uc5d0\uc11c \ub0b4\ubd80 \uad6c\uc870\ub97c \uc124\uba85\ud558\ub294 \uae00\uc740 \ub9e4\uc6b0 \ub9ce\uc9c0\ub9cc \uc774 \uae00\uc740 \uc2dc\uac01\uc801\uc73c\ub85c \ubcf4\uc5ec\uc8fc\uba74\uc11c \uce5c\uc808\ud558\uac8c \uc124\uba85\ud558\ub294 \uae00\uc774\ub77c\uace0 \uc0dd\uac01\ud574\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. <a href=\\"https://jser.dev/2023-07-11-overall-of-react-internals\\">\uae00\uc4f4\uc774\ub3c4 \ub9d0\ud588\ub4ef\uc774</a> React\uc758 \ucf54\ub4dc\ub294 \uac70\ub300\ud558\uace0 \ubaa8\ub450 \ud55c\ubc88\uc5d0 \uc774\ud574\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4(\ub610\ud55c \uc5c5\ub370\uc774\ud2b8\ub418\uba74\uc11c \ubc14\ub014 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4). \ucc9c\ucc9c\ud788 \uc774\ud574\ud558\uba74\uc11c \ubcf4\uc138\uc694!</p><h2 data-notion-block-id=\\"30b200b9-168c-495c-ad55-458aa83b12b4\\" id=\\"30b200b9-168c-495c-ad55-458aa83b12b4\\">Tanstack Query\ub97c \uc65c \uc368\uc57c \ud558\uc8e0?</h2><a href=\\"https://ui.dev/why-react-query\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ui.dev/why-react-query</a><p data-notion-block-id=\\"55a29a0e-f440-4cd1-be88-9d383430e60e\\"><b>\uc2ec\uc724\uc12d</b>: Redux saga\ub85c \uc11c\ubc84 \ub370\uc774\ud130\ub97c \ubc1b\uc544\uc624\ub294 \uc0ac\ub78c\ub4e4\uc5d0\uac8c\ub294 React Query\ub97c \uc4f0\ub294 \uc774\uc720\uc5d0 \ub300\ud574 \ucda9\ubd84\ud55c \uc774\ud574\ub97c \uac16\uace0 \uc811\uadfc\uc774 \uac00\ub2a5\ud558\uc9c0\ub9cc \ucc98\uc74c \uc2dc\uc791\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc774\ud574\ud558\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc740 \uc2dc\uac01\uc801\uc73c\ub85c \ubcf4\uc5ec\uc8fc\uba74\uc11c \uce5c\uc808\ud558\uac8c \uc124\uba85\ud574\uc90d\ub2c8\ub2e4. <a href=\\"https://blog.isquaredsoftware.com/2021/01/context-redux-differences/#final-thoughts\\">Redux \uac1c\ubc1c\uc790\ub3c4 \ub9d0\ud588\ub4ef\uc774</a>, Tanstack Query\ub294 \uc11c\ubc84 \uc0c1\ud0dc \uad00\ub9ac \ub77c\uc774\ube0c\ub7ec\ub9ac\uc774\uba70, \ubb38\uc81c \uc0c1\ud669\uacfc \uc77c\uce58\ud558\ub294 \ub3c4\uad6c\ub97c \uc0ac\uc6a9\ud558\uae30\ub97c \ubc14\ub77c\uace0 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"9399469d-45ed-4d8a-a6eb-1bf793278b51\\" id=\\"9399469d-45ed-4d8a-a6eb-1bf793278b51\\">\uac00\uc6b4\ub370 \uc815\ub82c\uc740 \ud798\ub4e4\ub2e4</h2><a href=\\"https://tonsky.me/blog/centering/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tonsky.me/blog/centering/</a><p data-notion-block-id=\\"e14f49c0-2b4d-45ea-b35e-d5bbbffe8922\\"><b>\uc2ec\uc724\uc12d</b>: \ubcf4\ud1b5 Flex \ub808\uc774\uc544\uc6c3\uc744 \uc0ac\uc6a9\ud574\uc11c \uac00\uc6b4\ub370 \uc815\ub82c\uc744 \ud558\uae30 \ub9c8\ub828\uc778\ub370, \uc800\uc790\ub294 \uadf8\ub798\ub3c4 \uac00\uc6b4\ub370 \uc815\ub82c\uc774 \uc548\ub418\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4\ub294 \uac83\uc744 \uc9c0\uc801\ud569\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \uc6f9 \uac1c\ubc1c\uc790\uac00 \uc774\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud574 \uc5ec\ub7ec\uac00\uc9c0 \ud574\uacb0\ucc45\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \ubb3c\ub860 \uc2e4\uc81c\ub85c \uac00\uc6b4\ub370 \uc815\ub82c\uc778\ub370 \ubcf4\uae30\uc5d0\ub294 \uac00\uc6b4\ub370 \uc815\ub82c\uc774 \uc544\ub2cc \uacbd\uc6b0\ub3c4 \uc788\uc73c\ubbc0\ub85c \uc644\uc804\ud55c \ud574\uacb0\ucc45\uc740 \uc544\ub2d9\ub2c8\ub2e4.. \uac00\uc6b4\ub370 \uc815\ub82c\ud558\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574\uc11c\ub294 <a href=\\"https://www.joshwcomeau.com/css/center-a-div/\\">How To Center a Div</a>\uc744 \ucc38\uace0\ud558\uc154\ub3c4 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"89d3a7e4-f2b6-4b81-9e57-10cdc330132b\\" id=\\"89d3a7e4-f2b6-4b81-9e57-10cdc330132b\\">CSS\ub85c \ub3c4\ud615 \ub9cc\ub4e4\uae30</h2><a href=\\"https://www.smashingmagazine.com/2024/05/modern-guide-making-css-shapes/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.smashingmagazine.com/2024/05/modern-guide-making-css-shapes/</a><p data-notion-block-id=\\"b32720f7-004c-4b92-ac11-33aaf1970136\\">\ud648\ud398\uc774\uc9c0\uc5d0 \ub3c4\ud615\uc774 \ub4e4\uc5b4\uac00\uac8c\ub418\uba74 \uc774\ubbf8\uc9c0\ub85c \ub54c\uc6b0\ub294 \uacbd\uc6b0\uac00 \ub300\ubd80\ubd84\uc774\uc9c0\ub9cc \uc5b4\ub835\uc9c0 \uc54a\uc740 \uacbd\uc6b0\ub294 CSS\ub85c\ub9cc \ub3c4\ud615\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4. \uc774\ub7f0 \uae30\ub2a5\uc744 \ubaa8\ub450 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\uc9c0\ub9cc \uc774\ub7f0 \ub3c4\ud615\ub3c4 CSS\ub85c \ub9cc\ub4e4 \uc218 \uc788\ub2e4\ub294 \uac83\ub9cc \uc54c\uace0 \ub2e4\uc2dc \uc774 \uae00\uc744 \ubc29\ubb38\ud574\ub3c4 \ub41c\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"9d0a352a-1d90-489e-9eb0-6852db3646b2\\" id=\\"9d0a352a-1d90-489e-9eb0-6852db3646b2\\">Grid masonry\uc5d0 \ub300\ud55c \uc0dd\uac01</h2><a href=\\"https://piccalil.li/blog/masonry-and-tabbing/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://piccalil.li/blog/masonry-and-tabbing/</a><p data-notion-block-id=\\"ec729dc2-f9a7-420a-b01b-4568a379e8a1\\">CSS Grid masonry\uac00 \uc544\uc9c1 \uc2e4\ud5d8\uc801\uc778 \ub2e8\uacc4\uc774\uc9c0\ub9cc Firefox\uc5d0\uc11c \uc694\uc18c\uc758 \uc21c\uc11c\uac00 \ub9e4\uc6b0 \uc774\uc0c1\ud558\uac8c \ubc30\uce58\ud558\ub294 \uac83\uc744 \uc9c0\uc801\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc2e4\ud5d8\uc801\uc778 \ub2e8\uacc4\uc774\uace0, \ub2e4\ub978 \uacf3\uc5d0\uc11c \ub9ce\uc774 \uc0ac\uc6a9\ud560 \uac83\uc740 \uc54c\uc9c0\ub9cc masonry layout\uc5d0 \ub300\ud574 \ubaa8\ub974\ub294 \uc0ac\ub78c\uc774 \ub9ce\uc744 \uac83\uc774\ub77c \uc0dd\uac01\ud574\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. JS\ub85c \uad6c\ud604\ud558\ub824\uba74 \ub108\ube44\uc640 \ub192\uc774\ub97c \uacc4\uc0b0\ud574\uc11c \ubc30\uce58\ud574\uc57c\ud569\ub2c8\ub2e4(<a href=\\"https://github.com/desandro/masonry\\">\uc608\uc2dc</a>).</p><h2 data-notion-block-id=\\"fbe65ae3-8936-43b7-92eb-38e9eb285e24\\" id=\\"fbe65ae3-8936-43b7-92eb-38e9eb285e24\\">Phoenix LiveView\ub294 Next.js\uc758 \uafc8\uc744 \uafb8\ub294\uac00</h2><a href=\\"https://www.phoenixframework.org/blog/phoenix-liveview-1.0-released\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.phoenixframework.org/blog/phoenix-liveview-1.0-released</a><p data-notion-block-id=\\"e2a72967-851a-487d-81b6-d8a49aa5fe43\\">LiveView\uc758 1.0 \ubc30\ud3ec\uac00 \ub2e4\uac00\uc654\ub2e4\uace0 \ud574\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \uc5b4\uadf8\ub85c \ub04c\ub824\uc11c \uac00\uc838\uc628 \uac83\ub3c4 \ub9de\uad6c\uc694. Blazor\uc640 \ube44\uc2b7\ud55c \ubc29\uc2dd(\uc18c\ucf13\uc73c\ub85c UI \ubcc0\uacbd\uc810 \ud1b5\uc2e0) \ub9cc\ub4e0 SSR \ud504\ub808\uc784\uc6cc\ud06c\uc785\ub2c8\ub2e4. \ub9e4\uc6b0 \uc88b\uc740 \ud504\ub808\uc784\uc6cc\ud06c\ub77c\uace0 \ubcf4\uae30\ub294 \ud798\ub4e4\uc9c0\ub9cc \uc774\ub7ec\ud55c \uc811\uadfc \ubc29\uc2dd\ub3c4 \uc788\ub2e4\ub77c\ub294 \uac83\uc744 \uc54c\uc544\ub450\uc168\uc73c\uba74 \ud569\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"e6ba3a2a-6c72-4b26-a22e-225f2afd80e4\\">Google I/O 2024</h1><p data-notion-block-id=\\"96104c93-49c9-4ddb-bed6-8caf15203f47\\">Google I/O\uc5d0\uc11c\ub3c4 Web\uc5d0 \ub300\ud55c \ubc1c\ud45c\ub97c \uc9c4\ud589\ud588\uc2b5\ub2c8\ub2e4. \uc694\uc57d\uc740 <a href=\\"https://developer.chrome.com/blog/web-at-io24?hl=ko\\">Google I/O 2024\uc5d0\uc11c \ubc1c\ud45c\ud55c 10\uac00\uc9c0 \uc5c5\ub370\uc774\ud2b8: \ubaa8\ub4e0 \uc6f9 \uac1c\ubc1c\uc790\ub97c \uc704\ud55c AI \uae30\ub2a5 \ud65c\uc6a9</a>\uc744 \ucc38\uace0\ud558\uc138\uc694. \uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/ee307831cb464aafb912fff97004d37e#9104b914-c2e2-4996-84f6-a8cb82cb8a42\\">Chrome \uc0ac\uc804\ub80c\ub354\ub9c1 API</a>\ub3c4 \uc788\ub124\uc694.</p><h2 data-notion-block-id=\\"2b489b3f-8104-442d-b1b4-b06cbeddec39\\" id=\\"2b489b3f-8104-442d-b1b4-b06cbeddec39\\">Web Feature Status</h2><a href=\\"https://web.dev/blog/web-platform-dashboard?hl=ko\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://web.dev/blog/web-platform-dashboard?hl=ko</a><p data-notion-block-id=\\"0fc42564-cfc7-40e7-a816-732f7731b8a0\\">4\uac1c \ube0c\ub77c\uc6b0\uc800\uc758 \uae30\ub2a5 \uc9c0\uc6d0 \ud604\ud669\uc744 \ud55c\ubc88\uc5d0 \ubcf4\uc5ec\uc8fc\ub294 \ub300\uc2dc\ubcf4\ub4dc\ub97c \ub9cc\ub4e4\uc5c8\uc2b5\ub2c8\ub2e4. CanIuse\uc758 \ub370\uc774\ud130\ub97c \ub300\uccb4\ud560 \uc218\ub294 \uc5c6\uc744 \uac83 \uac19\uc9c0\ub9cc \uc2e0\uaddc \uae30\ub2a5\uc774 \ubb34\uc5c7\uc774 \uc788\ub294\uc9c0\ub294 \ub354 \uc798 \ubcfc \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"b0c63d93-f63b-4f96-b56f-1532784c926c\\" id=\\"b0c63d93-f63b-4f96-b56f-1532784c926c\\">\ud604\uc7ac JavaScript \ud504\ub808\uc784\uc6cc\ud06c\uc758 \uc0c1\ud0dc</h2><a href=\\"https://developer.chrome.com/blog/frameworks-may-2024\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developer.chrome.com/blog/frameworks-may-2024</a><p data-notion-block-id=\\"ee49aa37-b24b-4637-ae2b-6d2060029ac7\\">2024\ub144 5\uc6d4 \ud604\uc7ac JavaScript \ud504\ub808\uc784\uc6cc\ud06c\uc758 \uae30\ub2a5\uacfc \uc544\ud0a4\ud14d\ucc98\uac00 \ub2ee\uc544\uac00\uace0 \uc788\uc73c\uba70, \uac01 \ud504\ub808\uc784\uc6cc\ud06c\ub9c8\ub2e4 \uc5b4\ub5a4 \uae30\ub2a5\uc73c\ub85c \ucc28\ubcc4\ud654\ub97c \uc774\ub8e8\uace0 \uc788\ub294\uc9c0 \ubd84\uc11d\ud55c \uc790\ub8cc\uc785\ub2c8\ub2e4. \ubb3c\ub860 \ub0b4\ubd80 \uad6c\uc131\uc774\ub098 \uc9c0\ud5a5\uc810\uc73c\ub85c \uc0bc\uace0 \uc788\ub294 \ubaa9\ud45c\ub294 \ubaa8\ub450 \ub2e4\ub974\uae30 \ub54c\ubb38\uc5d0 \uc815\ub9d0\ub85c \ubd84\uc11d\ud55c\ub2e4\uba74 \uac01 \ud504\ub808\uc784\uc6cc\ud06c\uc758 \ube14\ub85c\uadf8\ub97c \ubd10\uc57c\uaca0\ub124\uc694(<a href=\\"https://blog.angular.dev/angulars-vision-for-the-future-3cfca5e7b448\\">Angular</a>, <a href=\\"https://react.dev/blog/2024/02/15/react-labs-what-we-have-been-working-on-february-2024\\">React</a>, <a href=\\"https://remix.run/blog/merging-remix-and-react-router\\">Remix</a>, <a href=\\"https://nuxt.com/blog/looking-forward-2024\\">Nuxt</a>).</p><h2 data-notion-block-id=\\"573e1373-8623-4b1c-8d62-eb4359347395\\" id=\\"573e1373-8623-4b1c-8d62-eb4359347395\\">View Transition API</h2><a href=\\"https://developer.chrome.com/docs/web-platform/view-transitions?hl=ko\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developer.chrome.com/docs/web-platform/view-transitions?hl=ko</a><p data-notion-block-id=\\"5792fef6-0132-44fc-94f9-96edc4010bd8\\">\uc5ec\ub7ec \ud504\ub808\uc784\uc6cc\ud06c\uc5d0\uc11c View Transition API\uac00 \uc9c0\uc6d0\ud558\ub294 \uac83\uc740 \uae30\ubcf8\uc774 \ub418\uc5c8\uc73c\uba70, \ub2e4\uc591\ud55c \uc560\ub2c8\uba54\uc774\uc158\uc744 \ub9cc\ub4e4 \uc218 \uc788\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4(ex. <a href=\\"https://gsap.com/docs/v3/Plugins/Flip/\\">FLIP \uc560\ub2c8\uba54\uc774\uc158</a>).</p><h2 data-notion-block-id=\\"b8cb214d-d3d5-4f74-9c77-ade4991fc9f3\\" id=\\"b8cb214d-d3d5-4f74-9c77-ade4991fc9f3\\">Baseline to DX</h2><a href=\\"https://web.dev/blog/baseline-rum?hl=ko\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://web.dev/blog/baseline-rum?hl=ko</a><p data-notion-block-id=\\"9df66e19-56a1-4262-9df6-333bee3c4e59\\">RUM \ub370\uc774\ud130(\uc2e4\uc81c \uc0ac\uc6a9\uc790 \ub370\uc774\ud130)\ub97c \uc798 \ubcf4\uc774\uae30 \uc704\ud574 RUM \ud1b5\uacc4\ub97c \uacf5\uac1c\ud588\uc2b5\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \uac1c\ubc1c\uc790\uac00 \uac1c\ubc1c \ub3c4\uc911\uc5d0 \ub300\uc0c1 \ube0c\ub77c\uc6b0\uc800\uac00 \ud574\ub2f9 \uae30\ub2a5\uc744 \uc9c0\uc6d0\ud558\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\uae30 \uc704\ud574 \ub3c4\uad6c\uc5d0 \ud1b5\ud569\ud558\ub294 \uac83\uc744 \ubaa9\ud45c\ub85c \ud558\uace0 \uc788\ub2e4\uace0 \ud569\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"2d925bd1-2eb9-43fc-8786-b4ba4d8d934e\\">React Conf 2024</h1><p data-notion-block-id=\\"8dad7aa1-ff4e-48d7-bcdb-4dd5d8a88f2b\\">Meta\uc5d0\uc11c 2\ub144\ub9cc\uc5d0 React \ucee8\ud37c\ub7f0\uc2a4\ub97c \uac1c\ucd5c\ud588\uc2b5\ub2c8\ub2e4. \uadf8 \uc911\uc5d0\uc11c \uc88b\uc740 \uae00\uacfc \ud568\uaed8 \uc18c\uac1c\ud560 \uc218 \uc788\ub294 \uac83\ub4e4\uc744 \ubaa8\uc558\uc2b5\ub2c8\ub2e4(React 19\uc758 \uc2e0 \uae30\ub2a5\uc740 <a href=\\"https://ones-to-watch.ethansup.net/news/post/298d028d8e9c4d13b87a3ae9f00712fa#447f4cf6-64e5-4a14-a011-35ca657dfd6b\\">\uc5ec\ub7ec\uac00\uc9c0 \ucd9c\uc2dc \uc18c\uc2dd</a>\uc5d0 \ub123\uc5b4\ub1a8\ub358 <a href=\\"https://react.dev/blog/2024/04/25/react-19\\">React 19 beta \uae00</a>\uc744 \ucc38\uace0\ud558\uc138\uc694).</p><h2 data-notion-block-id=\\"273d7d04-732a-4f10-bf8a-defbda75bb65\\" id=\\"273d7d04-732a-4f10-bf8a-defbda75bb65\\">Remix\uc5d0\uc11c \ub2e4\uc2dc React-Router\ub85c</h2><a href=\\"https://remix.run/blog/merging-remix-and-react-router\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://remix.run/blog/merging-remix-and-react-router</a><p data-notion-block-id=\\"ce8ddd07-9d30-47ae-9fdf-a954ec594a7b\\">Remix\ub294 React Router\ub97c \uae30\ubc18\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c4 SSR \ud504\ub808\uc784\uc6cc\ud06c\uc785\ub2c8\ub2e4. React \uacf5\uc2dd\ubb38\uc11c\uc5d0\uc11c CRA\ub97c \ucd94\ucc9c\ud558\uc9c0 \uc54a\uace0, Remix\uc5d0\uc11c \ubc88\ub4e4\ub9c1 \ud234\uc744 Vite\ub85c \ubc14\uafb8\uac8c \ub418\uba74\uc11c(\uc774 \uacfc\uc815\uc5d0\uc11c Remix\uc5d0\uc11c SPA\ubaa8\ub4dc\ub97c \uc9c0\uc6d0\ud558\uaca0\ub2e4\uace0\ub3c4 \ud588\uc2b5\ub2c8\ub2e4), Remix\uc640 React Router\ub294 \ub2e4\ub97c \uac83\uc774 \uc5c6\ub2e4\uace0 \uc0dd\uac01\ud558\uac8c \ub418\uace0, Remix \ud328\ud0a4\uc9c0\ub97c React Router\ub85c \ubcc0\uacbd\ud558\ub294 \uacfc\uc815\uc744 \uac70\uce60 \uac83\uc774\ub77c\ub294 \ubc1c\ud45c\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"f8341745-e0c2-4a0c-94c5-1eba8d8e198e\\" id=\\"f8341745-e0c2-4a0c-94c5-1eba8d8e198e\\">RSC React\uc640 Node.js\ub9cc\uc73c\ub85c\ub9cc \uad6c\ud604\ud558\uae30</h2><a href=\\"https://react-server-components.epicweb.dev/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://react-server-components.epicweb.dev/</a><p data-notion-block-id=\\"13756d34-0847-4a62-ad0e-74394ec14b93\\">\ucee8\ud37c\ub7f0\uc2a4\uc5d0\uc11c\ub294 \uc11c\ubc84 \ucef4\ud3ec\ub10c\ud2b8 \uc9c0\uc6d0\uc758 \uc77c\ubd80\ub97c \uad6c\ud604\ud558\ub294 \uac83\ub9cc \ub098\uc654\uc9c0\ub9cc, RSC\uc758 \ub9ce\uc740 \ubd80\ubd84\uc744 \uad6c\ud604\ud558\ub294 \uc6cc\ud06c\uc0f5\uc744 \ub9cc\ub4e4\uc5c8\uae38\ub798 \uc774 \uc6cc\ud06c\uc0f5\uc73c\ub85c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. RSC\ub97c \ub2e4\ub978 \ud504\ub808\uc784\uc6cc\ud06c\ub4e4\uc774 \uc5b4\ub5bb\uac8c \uad6c\ud604\ud558\ub294\uc9c0\ub97c RSC\uc758 payload\ubd80\ud130 server action\uae4c\uc9c0 \ubaa8\ub450 \ud30c\uc545\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"7c39d4b0-fc93-4fbd-9b02-b095dbf45c63\\" id=\\"7c39d4b0-fc93-4fbd-9b02-b095dbf45c63\\">React Compiler</h2><a href=\\"https://github.com/reactwg/react-compiler/discussions/5\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/reactwg/react-compiler/discussions/5</a><a href=\\"https://www.youtube.com/watch?v=qOQClO3g8-Y\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=qOQClO3g8-Y</a><p data-notion-block-id=\\"09c41c63-ddab-455c-8df3-5ff78678b700\\">React Compiler\uc758 \ubca0\ud0c0\ubc84\uc804\uc744 \ucd9c\uc2dc\ud558\uba74\uc11c \uc5b4\ub5bb\uac8c \uc4f8 \uac83\uc778\uc9c0\uc640 \ub0b4\ubd80\ub294 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uc9c0 \uac04\ub7b5\ud558\uac8c \uc18c\uac1c\ud588\uc2b5\ub2c8\ub2e4. \uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/30480561-d12b-484b-9886-1eafeb5b6d35#2c964c01-95ca-4ec2-a409-d151ee87b9ea\\">React \ucef4\ud30c\uc77c\ub7ec\uc758 \ud0c0\uc785 \uc2dc\uc2a4\ud15c</a>\uc758 \uc800\uc790\uac00 Deep dive\ub97c \ubc1c\ud45c\ud588\uc2b5\ub2c8\ub2e4. <a href=\\"https://www.recompiled.dev/tags/compiler/\\">\ube14\ub85c\uadf8 \uae00</a>\uc744 \uc77d\uc73c\uba74 \ub354 \uc798 \uc774\ud574\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. </p><p data-notion-block-id=\\"d52c4702-be89-4074-a0bc-dfd18899e3d9\\"></p>"}')}}]);